    n = 15
    total_kawaii = 0
    for m in range(1, n + 1):
        # a(n, m) is the number of kawaii sequences of length n with max element m.
        # The set of elements is {1, ..., m}.
        # DP state: dp[i][j] = number of sequences of length i with elements from {1, ..., m}
        # such that the largest k for which we have found i_1 < ... < i_k is j.
        dp = [[0] * (m + 1) for _ in range(n + 1)]
        dp[0][0] = 1
        for i in range(n):
            for j in range(m + 1):
                if dp[i][j] == 0:
                    continue
                if j < m:
                    # Elements that keep the state at j: {1, ..., j} and {j+2, ..., m}
                    # There are j + (m - (j+1)) = m - 1 such elements.
                    dp[i+1][j] += dp[i][j] * (m - 1)
                    # Element that moves the state to j+1: {j+1}
                    dp[i+1][j+1] += dp[i][j] * 1
                else:
                    # State is m, so any element from {1, ..., m} keeps the state at m.
                    dp[i+1][m] += dp[i][m] * m
        total_kawaii += dp[n][m]
    return total_kawaii

